-- Quranically discipline pedagogy v1: accountable teaching -> understanding -> lived relevance.
-- Each practical learning guide cites ONE existing canonical citation of the SAME article.
-- Religious and historical application examples are editorial proposals, not new Sunnah rituals or fatwas.
CREATE TABLE IF NOT EXISTS discipline_learning_guides(
 id TEXT PRIMARY KEY,
 article_id TEXT NOT NULL UNIQUE REFERENCES encyclopedia_articles(id),
 primary_citation_id TEXT NOT NULL REFERENCES encyclopedia_citations(id),
 source_teaching TEXT NOT NULL DEFAULT '',
 how_to_understand TEXT NOT NULL DEFAULT '',
 everyday_application TEXT NOT NULL DEFAULT '',
 everyday_example TEXT NOT NULL DEFAULT '',
 boundaries TEXT NOT NULL DEFAULT '',
 interpretation_notes TEXT NOT NULL DEFAULT '',
 review_status TEXT NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','source_checked','scholar_reviewed')),
 status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),
 updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_discipline_learning_status ON discipline_learning_guides(status,article_id);

INSERT OR IGNORE INTO discipline_learning_guides(id,article_id,primary_citation_id,source_teaching,how_to_understand,everyday_application,everyday_example,boundaries,interpretation_notes,review_status,status) VALUES('quran-sabr-application','patience-quranic-theme','patience-quranic-theme-r1','Qur’an 2:153 connects seeking help with patience and prayer. This description does not replace a named Tafsir.','Read the full verse and its surrounding passage; identify what the verse states before adding interpretations. Check any broader claim against an attributed Tafsir rather than translation keywords alone.','Set aside a short, manageable time to read the verse and reflect. Pair prayer and patient conduct with an appropriate ethical action toward the hardship; this is an optional editorial learning suggestion, not a new prescribed ritual.','If worried about a difficult obligation, read Qur’an 2:153 in context, write down one immediate responsibility and one appropriate person or service to ask for help.','Patience does not mean tolerating abuse, avoiding necessary care, or assuming hardship has a guaranteed timetable. No particular recitation count is established here.','Specific meanings and context require recognised Tafsir. Interpretive differences and personal legal questions are outside this educational exercise.','pending','published');

INSERT OR IGNORE INTO discipline_learning_guides(id,article_id,primary_citation_id,source_teaching,how_to_understand,everyday_application,everyday_example,boundaries,interpretation_notes,review_status,status) VALUES('sunnah-truthfulness-application','truthfulness-in-sunnah','truthfulness-in-sunnah-r1','Sahih al-Bukhari 6094 links truthfulness with righteousness and describes the danger of habitual falsehood. Attribution and collection reference should remain visible.','Identify the actual report, speaker, collection and published explanation. Distinguish the Prophetic teaching from additional editorial examples and from legal rulings about complex circumstances.','In ordinary communication, verify a statement before repeating it; if a claim is mistaken, correct it clearly. This is an illustrative application of honesty, not a reported fixed Prophetic exercise.','Before forwarding uncertain information about another person, check whether it is accurate and necessary; if not, refrain or seek clarification.','This entry does not supply a complete ruling on testimony, privacy, safety or every case of disclosure. Those issues can require qualified scholarship and context.','Any Hadith grade or interpretive explanation must be attributed to a specific authority; Quranically does not independently regrade narrations.','pending','published');

INSERT OR IGNORE INTO discipline_learning_guides(id,article_id,primary_citation_id,source_teaching,how_to_understand,everyday_application,everyday_example,boundaries,interpretation_notes,review_status,status) VALUES('seerah-hijrah-application','hijrah-to-madinah','hijrah-to-madinah-r1','Qur’an 9:40 mentions reassurance in the cave; the detailed journey is also described in Sahih al-Bukhari 3905. These are different evidentiary layers.','Place an event in its historical circumstances, identify who reported each detail, and separate Qur’anic evidence from later historical reconstruction.','Reflect on careful preparation, trustworthy companionship and reassurance in difficulty. Translate those general virtues into responsible planning rather than treating the Prophet’s unique journey as a literal blueprint for migration.','For a difficult change, write down the practical preparation required, the trustworthy people you could consult and the ethical duties you must preserve.','This event does not automatically impose a modern migration duty, guarantee a particular outcome or validate every popular travel anecdote.','Dates, itineraries and disputed reports require edition-specific historical comparison; the sequence presented here is educational, not a verified exhaustive chronology.','pending','published');

INSERT OR IGNORE INTO discipline_learning_guides(id,article_id,primary_citation_id,source_teaching,how_to_understand,everyday_application,everyday_example,boundaries,interpretation_notes,review_status,status) VALUES('guidance-anger-application','anger-and-self-restraint','anger-and-self-restraint-r1','Qur’an 3:134 praises those who restrain anger and forgive, while Sahih al-Bukhari 6116 records repeated advice not to give way to anger.','Understand the source teachings as ethical guidance; do not equate restraint with ignoring injustice, allowing harm or declaring a personal legal ruling.','When upset, avoid immediate hurtful words where safe, give yourself room to respond, and seek a respectful conversation later. This is an optional practical suggestion, not a narrated ritual with a specified count.','In a family disagreement, postpone a retaliatory message, check what actually happened, then offer a calm response or appropriate apology when safe.','Do not advise someone to remain in an abusive or dangerous situation. Seek trusted local support, emergency help or professional care where needed.','Disputed family, divorce, violence and legal matters depend on circumstances and qualified scholarly and professional guidance; no automatic fatwa is generated.','pending','published');
